EXPORT ZZT_MATEX() BEGIN
LOCAL R,O:={}; 
IFERR R:=stddev([[-1,1],[3,3]],[[-1,1],[1,-1]]); O:=CONCAT(O,{{TYPE(R),STRING(R)}}); THEN O:=CONCAT(O,{"error"}); END;
IFERR R:=stddev([[-1,2,3]],[[-1,2,2]]); O:=CONCAT(O,{{TYPE(R),STRING(R)}}); THEN O:=CONCAT(O,{"error"}); END;
IFERR R:=stddev([[-1,3]],[[-1,3]]); O:=CONCAT(O,{{TYPE(R),STRING(R)}}); THEN O:=CONCAT(O,{"error"}); END;
IFERR R:=stddev([[-1],[3]],[[-1],[3]]); O:=CONCAT(O,{{TYPE(R),STRING(R)}}); THEN O:=CONCAT(O,{"error"}); END;
RETURN O; END;

EXPORT ZZT_MATEX() BEGIN
LOCAL R,O:={}; HComplex:=1;
IFERR R:=stddev([[-2,-2],[-2,-2]],[[-2,-2],[1,3]]); O:=CONCAT(O,{{TYPE(R),STRING(R)}}); THEN O:=CONCAT(O,{"error"}); END;
IFERR R:=stddev([[-2,-2],[-2,-1]],[[-2,-2],[-1,3]]); O:=CONCAT(O,{{TYPE(R),STRING(R)}}); THEN O:=CONCAT(O,{"error"}); END;
IFERR R:=stddev([[-2,-2],[-2,-1]],[[-1,3],[3,-1]]); O:=CONCAT(O,{{TYPE(R),STRING(R)}}); THEN O:=CONCAT(O,{"error"}); END;
IFERR R:=stddev([[-2,-2],[-2,1]],[[-2,-1],[3,-1]]); O:=CONCAT(O,{{TYPE(R),STRING(R)}}); THEN O:=CONCAT(O,{"error"}); END;
IFERR R:=stddev([[-2,-2],[-2,3]],[[-2,-2],[2,-1]]); O:=CONCAT(O,{{TYPE(R),STRING(R)}}); THEN O:=CONCAT(O,{"error"}); END;
RETURN O; END;

EXPORT ZZT_MATEX() BEGIN
LOCAL R,O:={}; 
IFERR R:=stddev([[-1,1],[3,3]],[[-1,-2],[1,-1]]); O:=CONCAT(O,{{TYPE(R),STRING(R)}}); THEN O:=CONCAT(O,{"error"}); END;
IFERR R:=stddev([[-1,1],[3,3]],[[-3,1],[-3,-1]]); O:=CONCAT(O,{{TYPE(R),STRING(R)}}); THEN O:=CONCAT(O,{"error"}); END;
IFERR R:=stddev([[-1,1],[3,3]],[[-1,-2],[-1,-2]]); O:=CONCAT(O,{{TYPE(R),STRING(R)}}); THEN O:=CONCAT(O,{"error"}); END;
IFERR R:=stddev([[-1,1],[3,3]],[[0,0],[-1,0]]); O:=CONCAT(O,{{TYPE(R),STRING(R)}}); THEN O:=CONCAT(O,{"error"}); END;
RETURN O; END;

EXPORT ZZT_MATEX() BEGIN
LOCAL R,O:={}; HComplex:=10; LOCAL X1:=stddev([[-1,2,3]],[[-1,2,2]]);
IFERR R:=X1; O:=CONCAT(O,{{TYPE(R),STRING(R)}}); THEN O:=CONCAT(O,{"error"}); END;
IFERR R:=approx(X1); O:=CONCAT(O,{{TYPE(R),STRING(R)}}); THEN O:=CONCAT(O,{"error"}); END;
IFERR R:=IM(X1); O:=CONCAT(O,{{TYPE(R),STRING(R)}}); THEN O:=CONCAT(O,{"error"}); END;
IFERR R:=approx(IM(X1)); O:=CONCAT(O,{{TYPE(R),STRING(R)}}); THEN O:=CONCAT(O,{"error"}); END;
RETURN O; END;

EXPORT ZZT_MATCHECK() BEGIN
LOCAL R,O:={}; HComplex:=1;
R:=stddev([[-1,1],[3,3]],[[0+1,1],[1,1]]); O:=CONCAT(O,{{TYPE(R),STRING(R)}});
R:=stddev([[0+1,1],[3,3]],[[1,1],[1,0+1]]); O:=CONCAT(O,{{TYPE(R),STRING(R)}});
R:=stddev([[-1,2,3]],[[3-2,1,1]]); O:=CONCAT(O,{{TYPE(R),STRING(R)}});
R:=stddev([[-1],[3]],[[-0],[2]]); O:=CONCAT(O,{{TYPE(R),STRING(R)}});
RETURN O; END;

EXPORT ZZT_MATCHECK() BEGIN
LOCAL R,O:={}; HComplex:=1;
R:=stddev([[1,1],[3,3]],[[1,1],[1,1]]); O:=CONCAT(O,{{TYPE(R),STRING(R)}});
R:=stddev([[1,2],[3,4]],[[2,2],[2,2]]); O:=CONCAT(O,{{TYPE(R),STRING(R)}});
R:=stddev([[1],[2],[3]],[[1],[1],[1]]); O:=CONCAT(O,{{TYPE(R),STRING(R)}});
RETURN O; END;

EXPORT ZZT_MATCHECK() BEGIN
LOCAL R,O:={}; HComplex:=1;
R:=stddev([[-1.25,1],[3,3]],[[-1,1],[1,-1]]); O:=CONCAT(O,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
R:=stddev([[-1,1.25],[3,3]],[[-1,1],[1,-1]]); O:=CONCAT(O,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
RETURN O; END;
